mapper.update:
update `order` set is_lock=true
where order_id=#{orderId}
and is_ack=false and is_lock=false and state_now=0

update `order` set is_refund=true,is_lock=true
where order_id=#{orderId} and user_id=#{userId}
and is_ack=true and is_lock=false and is_refund=false and is_complete=false and state_now = 1

update `order` set is_ack=true,state_now=1
where order_id=#{orderId}
and is_ack=false and is_lock=false and is_refund=false and is_complete=false and state_now=0

update `order` set is_refund=true, is_lock=true
where order_id=#{orderId} and merchant_id=#{merchantId}
  and is_ack=true and is_lock=false and is_refund=false and is_complete=false and state_now = 1

update `order` set state_now= 2
where order_id=#{orderId} and merchant_id=#{merchantId}
  and is_ack=true and is_lock=false and is_refund=false and is_complete=false and state_now = 1

update `order` set state_now= 3
where order_id=#{orderId} and merchant_id=#{merchantId}
  and is_ack=true and is_lock=false and is_refund=false and is_complete=false and state_now = 2

update `order` set rider_id= #{riderId}
where order_id=#{orderId} and rider_id is null
  and is_ack=true and is_lock=false and is_refund=false and is_complete=false and (state_now = 2 or state_now =3)

update `order` set state_now= 4
where order_id=#{orderId} and rider_id=#{riderId}
  and is_ack=true and is_lock=false and is_refund=false and is_complete=false and state_now = 3

update `order` set state_now= 5
where order_id=#{orderId} and rider_id=#{riderId}
  and is_ack=true and is_lock=false and is_refund=false and is_complete=false and state_now = 4

update `order` set state_now= 6,is_complete=true,is_lock=true
where order_id=#{orderId} and user_id=#{userId}
  and is_ack=true and is_lock=false and is_refund=false and is_complete=false and state_now = 5
